<script setup lang="ts">
import{ref,watch,onBeforeUnmount}from'vue';import{Search}from'@lucide/vue';
const props=defineProps<{clinicId:string;allowSubjects:boolean;initialQuery?:string}>(),emit=defineEmits(['selected','denied']);
const query=ref(props.initialQuery||''),patients=ref<any[]>([]),subjects=ref<any[]>([]),patientPage=ref<any>(null),subjectPage=ref<any>(null),loading=ref(false),error=ref(''),loaded=ref(false);let generation=0,controller:AbortController|null=null;
function clearResults(){generation++;controller?.abort();controller=null;patients.value=[];subjects.value=[];patientPage.value=null;subjectPage.value=null;loading.value=false;loaded.value=false;error.value='';}
watch(query,clearResults);watch(()=>[props.clinicId,props.allowSubjects],()=>{query.value='';clearResults();});
async function search(kind='all',more=false){if(loading.value)return;const q=query.value.trim();if(q.length<2||q.length>100){error.value='请输入2至100字的姓名或电话线索。';return;}if(!more)clearResults();const gen=++generation;controller=new AbortController();const own=controller;loading.value=true;error.value='';const params=new URLSearchParams({clinicId:props.clinicId,q,kind:props.allowSubjects?kind:'patients',limit:'20'});if(more)params.set('cursor',kind==='patients'?patientPage.value.nextCursor:subjectPage.value.nextCursor);const timer=setTimeout(()=>own.abort(),12000);
 try{const r=await fetch('/api/v1/frontdesk/people?'+params,{credentials:'same-origin',signal:own.signal}),b=await r.json().catch(()=>({}));if(gen!==generation)return;if(!r.ok){if(r.status===401||r.status===403){clearResults();emit('denied',r.status);return;}if(r.status===409){clearResults();error.value=b.message||'目录已变化，请重新检索。';return;}throw Error(b.message||'检索失败，请重试。');}
  if(b.patientPage){patients.value=more?[...patients.value,...b.patients]:b.patients;patientPage.value=b.patientPage;}if(b.subjectPage){subjects.value=more?[...subjects.value,...b.subjects]:b.subjects;subjectPage.value=b.subjectPage;}loaded.value=true;
 }catch(e){if(gen===generation)error.value=e instanceof Error&&e.name!=='AbortError'?e.message:'检索超时，请重新检索。';}finally{clearTimeout(timer);if(gen===generation){loading.value=false;controller=null;}}}
function choose(kind:string,p:any){clearResults();emit('selected',{kind,person:p});}
function clear(){query.value='';clearResults();}
onBeforeUnmount(clearResults);
</script>
<template><section class="fd-identity-search"><label>核实并选择本诊所已有身份<div class="fi-search"><input v-model="query" maxlength="100" placeholder="输入姓名或电话，至少两个字符" @keydown.enter.prevent="search()"/><button type="button" class="b-button outline small" :disabled="loading" @click="search()"><Search :size="15"/>检索</button><button v-if="query" type="button" class="f-text" @click="clear">清空检索</button></div></label><p class="b-help">患者档案仅检索本诊所已有建档、预约或就诊关联。姓名、电话相同也需人工核实，不自动合档。</p><div v-if="error" class="b-alert error" role="alert">{{error}}</div><p v-if="loading" role="status">正在检索身份…</p>
 <template v-if="loaded"><div v-if="patientPage" class="fi-results"><strong>患者档案 · 已显示 {{patients.length}} / {{patientPage.total}}</strong><button v-for="p in patients" :key="p.id" type="button" class="fi-candidate" :disabled="loading" @click="choose('patient',p)"><span>{{p.name}} · {{p.phone||'未留电话'}}</span><small>档案 {{p.id.slice(0,8).toUpperCase()}} · 出生日期 {{p.birthDate||'未提供'}}</small></button><p v-if="!patientPage.total" class="b-help">本诊所关联范围内未匹配到患者档案。</p><button v-if="patientPage.nextCursor" type="button" class="b-button outline small" :disabled="loading" @click="search('patients',true)">继续读取患者档案</button></div>
 <div v-if="allowSubjects&&subjectPage" class="fi-results"><strong>预约主体 · 已显示 {{subjects.length}} / {{subjectPage.total}}</strong><p class="b-help">姓名及电话取本店预约日期最近的一次安排，仅作人工身份核实线索。</p><button v-for="p in subjects" :key="p.id" type="button" class="fi-candidate" :disabled="loading" @click="choose('subject',p)"><span>{{p.name}} · {{p.phone}}</span><small>主体 {{p.id.slice(0,8).toUpperCase()}} · 来源预约 {{p.sourceAppointmentId.slice(0,8).toUpperCase()}}</small></button><p v-if="!subjectPage.total" class="b-help">本诊所未匹配到预约主体。</p><button v-if="subjectPage.nextCursor" type="button" class="b-button outline small" :disabled="loading" @click="search('subjects',true)">继续读取预约主体</button></div></template>
</section></template>
<style scoped>
.fd-identity-search{font-size:15px;line-height:1.65;min-width:0}.fi-search{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:8px 0}.fi-search input{min-width:0;flex:1 1 200px}.fi-results{margin:14px 0;padding:12px;border:1px solid #dce7e1;border-radius:8px}.fi-results>strong{display:block;font-size:14px;color:#305c4c;margin-bottom:10px}.fi-candidate{display:block;width:100%;text-align:left;padding:12px;border:1px solid #dce7e1;background:#f6faf7;border-radius:8px;margin:9px 0;color:#234b3e;font:inherit;overflow-wrap:anywhere;cursor:pointer}.fi-candidate:disabled{opacity:.65;cursor:wait}.fi-candidate small{display:block;font-size:13px;color:#64756d;margin-top:4px}.fd-identity-search .b-help{font-size:14px;line-height:1.65}@media(max-width:700px){.fi-results{padding:10px}.fi-candidate{padding:10px}.fi-search input{flex-basis:100%}}
</style>
